 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    border = next((v for row in g for v in row if v not in (5,)), None)
    # The framing color is the non-background color; fill only background cells
    # that cannot reach the exterior without crossing that frame.
    bg = next(v for row in g for v in row if v != border)
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h-1) or c in (0, w-1)) and g[r][c] == bg:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]==bg:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg and (r,c) not in seen:
                g[r][c] = 4
    return g

